import java.io.BufferedReader
import java.io.InputStreamReader

fun readLineCustom(): String {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    return reader.readLine()
}

fun solve(tag: String, pat: String): Boolean {
    val tagIter = tag.iterator()

    for (patChr in pat) {
        while (true) {
            if (!tagIter.hasNext()) return false
            val tagChr = tagIter.nextChar()
            if (tagChr == patChr) break
        }
    }
    return true
}

fun main() {
    if (solve(readLineCustom().trim(), "hello")) {
        println("YES")
    } else {
        println("NO")
    }
}

